function run(env, waitListen = true) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [SERVER], { cwd: dir, env: { ...process.env, ...env } });
    let stdout = '', stderr = '';
    child.stdout.on('data', (d) => {
      stdout += d;
      const m = /:(\d+)\n/.exec(stdout);
      if (m && waitListen) resolve({ child, port: Number(m[1]), stdout, get stderr() { return stderr; } });
    });
    child.stderr.on('data', (d) => { stderr += d; });
    child.on('exit', (code) => resolve({ code, stdout, stderr }));
  });
}

async function req(port, method, p, { body, type } = {}) {
  const headers = {};
  if (type) headers['content-type'] = type;
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1', () => {
      const b = body === undefined ? Buffer.alloc(0) : Buffer.from(body);
      let h = `${method} ${p} HTTP/1.1\r\nHost: x\r\nConnection: close\r\n`;
      for (const [k, v] of Object.entries(headers)) h += `${k}: ${v}\r\n`;
      if (body !== undefined) h += `Content-Length: ${b.length}\r\n`;
      s.write(h + '\r\n'); s.end(b);
    });
    let data = '';
    s.on('data', (d) => { data += d; });
    s.on('close', () => {
      const [head, ...rest] = data.split('\r\n\r\n');
      const status = head.split(' ')[1];
      const ct = (/content-type: (.*)/i.exec(head) || [])[1];
      resolve(`${status} [${ct}] ${rest.join('')}`);
    });
    s.on('error', (e) => resolve('ERR ' + e.message));
  });
}

